-- Flywheel — one-shot bootstrap for a fresh database.
--
-- Paste the whole file into Supabase -> SQL Editor -> New query -> Run. It is
-- the schema, the access table and every migration in order, so a new project
-- lands exactly where production is in a single paste.
--
-- Safe to re-run: every statement either checks for existence first or is a
-- no-op the second time.
--
-- Generated by scripts/build-bootstrap.mjs — do not edit by hand.

-- ===========================================================
-- schema.sql
-- ===========================================================

-- Experiment Changelog Portal — Supabase schema
-- Run this in the Supabase SQL Editor (Dashboard → SQL Editor → New query)

create table if not exists experiments (
  id uuid primary key default gen_random_uuid(),
  date_logged timestamptz,
  logged_by text not null default '',
  client text not null default '',
  industry text not null default '',
  use_case text not null default '',
  bucket text not null default '',
  experiment_name text not null default '',
  metric_type text not null default '',
  metric_label text not null default '',
  before_value text not null default '',
  after_value text not null default '',
  pct_change text not null default '',
  direction text not null default '',
  evidence_note text not null default '',
  endorsements text not null default '',
  pinned text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists experiment_reactions (
  id uuid primary key default gen_random_uuid(),
  experiment_id uuid not null references experiments(id) on delete cascade,
  user_identity text not null,
  reaction text not null check (reaction in ('up', 'down')),
  created_at timestamptz not null default now(),
  unique(experiment_id, user_identity, reaction)
);

create index if not exists idx_experiments_client on experiments(client);
create index if not exists idx_experiments_bucket on experiments(bucket);
create index if not exists idx_experiments_date on experiments(date_logged desc);
create index if not exists idx_reactions_experiment on experiment_reactions(experiment_id);

-- Row Level Security (optional but recommended)
-- Enable RLS on both tables. The service role key bypasses RLS,
-- so the Next.js API routes will work as-is.
alter table experiments enable row level security;
alter table experiment_reactions enable row level security;


-- ===========================================================
-- allowed_users (not in schema.sql — see build-bootstrap.mjs)
-- ===========================================================

-- Who is allowed to sign in. Every request is checked against this table, so a
-- database without it lets nobody in — including you.
create table if not exists allowed_users (
  id uuid primary key default gen_random_uuid(),
  email text unique not null,
  role text default 'member' check (role in ('admin', 'member')),
  name text,
  invited_by text,
  created_at timestamptz default now()
);

-- Add yourself before signing in, or run scripts/seed-dev.mjs which does it for
-- you along with some example experiments:
--   insert into allowed_users (email, role, name)
--   values ('you@squadstack.ai', 'admin', 'Your Name')
--   on conflict (email) do nothing;


-- ===========================================================
-- migrations/001_add_prompt.sql
-- ===========================================================

-- Adds a column for the prompt snippet behind an experiment.
--
-- The log form used to collect "Prompt used" but the experiments table had
-- nowhere to put it, so every value typed there was discarded on save. The
-- field is removed from the form until this migration is applied.
--
-- Run in Supabase → SQL Editor, then:
--   1. add `prompt: row.prompt ?? ""` to rowToEntry in lib/experiments.ts
--   2. add `prompt: entry.prompt ?? ""` to payloadToRecord in lib/experiments.ts
--   3. restore the "Prompt used" textarea in src/dashboard.js (step 1 of the
--      form) and its line in syncStep()

alter table experiments
  add column if not exists prompt text not null default '';


-- ===========================================================
-- migrations/002_add_owner_email.sql
-- ===========================================================

-- Identify the owner of an experiment by email instead of first name.
--
-- WHY
-- `logged_by` holds a display first name ("Saloni", "Rajat"). Edit permission
-- has to match the signed-in user against that string, which breaks the moment
-- two people share a first name — and it silently reassigned owners when a name
-- was missing from the form's dropdown. Email is unique and stable.
--
-- `logged_by` stays as the display name shown in the UI. `owner_email` becomes
-- the thing permission checks actually compare.
--
-- HOW TO RUN
-- Supabase dashboard -> SQL Editor -> New query -> paste this -> Run.
-- The app detects the column automatically; no redeploy needed.

alter table experiments
  add column if not exists owner_email text not null default '';

-- Backfill: match each row's logged_by against the first name on the invite
-- list. Rows whose owner is not on the invite list are left blank and keep
-- falling back to name matching until someone edits them.
update experiments e
set owner_email = u.email
from allowed_users u
where e.owner_email = ''
  and e.logged_by <> ''
  and lower(split_part(u.name, ' ', 1)) = lower(e.logged_by);

create index if not exists idx_experiments_owner_email
  on experiments (owner_email);

-- Check what the backfill could not resolve:
--   select distinct logged_by from experiments where owner_email = '';


-- ===========================================================
-- migrations/003_api_tokens.sql
-- ===========================================================

-- Personal API tokens, so an AI assistant can log experiments as a real person.
--
-- WHY
-- The API only accepts a browser session cookie, so a skill running in someone's
-- Claude cannot write anything as them. A token binds a request to one email
-- permanently: whatever it creates is owned by that person, forever, and shows
-- their name in the changelog.
--
-- SECURITY NOTES
--   * Only the SHA-256 hash is stored. The plaintext token is shown once, at
--     creation, and cannot be recovered — losing it means making a new one.
--   * `prefix` is the first few visible characters, kept purely so a person can
--     tell their tokens apart in the UI.
--   * Revoking is a timestamp, not a delete, so an audit trail survives.
--   * Access is still gated on allowed_users at request time, so removing
--     someone from the invite list kills their tokens immediately.
--
-- HOW TO RUN
-- Supabase dashboard -> SQL Editor -> New query -> paste -> Run.
-- The app detects the table automatically; no redeploy needed.

create table if not exists api_tokens (
  id uuid primary key default gen_random_uuid(),
  user_email text not null,
  name text not null default '',
  token_hash text not null unique,
  prefix text not null default '',
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  revoked_at timestamptz
);

create index if not exists idx_api_tokens_hash on api_tokens (token_hash);
create index if not exists idx_api_tokens_user on api_tokens (user_email);

alter table api_tokens enable row level security;


-- ===========================================================
-- migrations/004_comments.sql
-- ===========================================================

-- Comments on experiments, so anyone with access can discuss a logged experiment.
--
-- HOW TO RUN
-- Supabase dashboard -> SQL Editor -> New query -> paste -> Run.

create table if not exists experiment_comments (
  id uuid primary key default gen_random_uuid(),
  experiment_id uuid not null,
  author_email text not null,
  author_name text not null default '',
  body text not null,
  created_at timestamptz not null default now()
);

create index if not exists idx_comments_experiment on experiment_comments (experiment_id, created_at);
create index if not exists idx_comments_author on experiment_comments (author_email);

alter table experiment_comments enable row level security;


-- ===========================================================
-- migrations/005_comment_cascade.sql
-- ===========================================================

-- Comments should not outlive the experiment they are attached to.
--
-- WHY
-- experiment_reactions has a foreign key with `on delete cascade`, so reactions
-- clean themselves up. experiment_comments (migration 004) has neither, so
-- deleting an experiment left its whole thread in the table: invisible in the
-- UI, attached to an id nothing resolves, and counted by nothing.
--
-- The DELETE route also clears comments itself, so this is not urgent — but the
-- route cannot help when rows are deleted straight from the Supabase console,
-- which is exactly when it is easiest to forget.
--
-- HOW TO RUN
-- Supabase dashboard -> SQL Editor -> New query -> paste -> Run.
-- Safe to re-run, and safe to run while the app is live.

-- Any comments already orphaned by a delete that happened before this.
delete from experiment_comments c
where not exists (
  select 1 from experiments e where e.id = c.experiment_id
);

alter table experiment_comments
  drop constraint if exists experiment_comments_experiment_id_fkey;

alter table experiment_comments
  add constraint experiment_comments_experiment_id_fkey
  foreign key (experiment_id) references experiments(id) on delete cascade;


-- ===========================================================
-- migrations/006_reaction_identity.sql
-- ===========================================================

-- Reactions are recorded against an email, not a first name.
--
-- WHY
-- experiment_reactions.user_identity used to hold whatever name the browser
-- sent. Two people called Saloni shared one vote, and because the value came
-- from the request body rather than the session, a crafted request could react
-- as somebody else — or undo their reaction. The API now always writes the
-- signed-in email, the same identity ownership uses.
--
-- Rows written before this still hold first names. They keep counting toward
-- the totals; they just do not belong to anyone, so nobody can un-toggle them.
-- This backfills the ones that can be resolved unambiguously.
--
-- HOW TO RUN
-- Supabase dashboard -> SQL Editor -> New query -> paste -> Run.
-- Safe to re-run.

update experiment_reactions r
set user_identity = u.email
from allowed_users u
where r.user_identity not like '%@%'
  and lower(r.user_identity) = lower(split_part(u.name, ' ', 1))
  and (
    select count(*) from allowed_users u2
    where lower(split_part(u2.name, ' ', 1)) = lower(r.user_identity)
  ) = 1;

-- One person, one reaction of each kind, per experiment. The API checks this
-- before inserting, but two quick clicks used to be able to race past it.
delete from experiment_reactions a
using experiment_reactions b
where a.ctid > b.ctid
  and a.experiment_id = b.experiment_id
  and a.user_identity = b.user_identity
  and a.reaction = b.reaction;

create unique index if not exists uniq_reaction_per_person
  on experiment_reactions (experiment_id, user_identity, reaction);


-- ===========================================================
-- migrations/007_comment_replies.sql
-- ===========================================================

-- Replies and edits on comments.
--
-- WHY
-- Comments were a flat list: no way to answer a specific question, and no way to
-- fix a typo without deleting and re-posting. Threading is also what makes
-- notifications sensible later — "someone replied to you" needs a parent.
--
-- parent_id cascades, so deleting a comment takes its replies with it, and
-- migration 005's cascade on experiment_id means deleting an experiment still
-- clears the whole thread.
--
-- The app works with or without this migration: it probes for the columns and
-- falls back to flat, uneditable comments if they are missing. Running it turns
-- the features on with no redeploy.
--
-- HOW TO RUN
-- Supabase dashboard -> SQL Editor -> New query -> paste -> Run.
-- Safe to re-run.

alter table experiment_comments
  add column if not exists parent_id uuid references experiment_comments(id) on delete cascade;

alter table experiment_comments
  add column if not exists edited_at timestamptz;

create index if not exists idx_comments_parent on experiment_comments (parent_id);


-- ===========================================================
-- migrations/008_skill_version.sql
-- ===========================================================

-- Which version of the skill a key was downloaded with.
--
-- WHY
-- The skill file is generated once and lives on someone's machine forever.
-- When its instructions change — as they did when PATCH stopped needing the
-- whole entry, and when replies and reactions arrived — every copy already out
-- there keeps following the old rules, and nobody has any way to know.
--
-- Recording the version at download time lets the Connect drawer say "yours is
-- out of date" instead of leaving people to guess. Existing keys have no
-- version, which is treated as "older than the first version we tracked" —
-- correct, since they all predate this column.
--
-- HOW TO RUN
-- Supabase dashboard -> SQL Editor -> New query -> paste -> Run.
-- Safe to re-run. The app works without it: the drawer simply stops flagging
-- stale keys until it is applied.

alter table api_tokens add column if not exists skill_version integer;

